<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\ValueObject\UserConsentedScopesTrustedClientVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;

final class UserConsentedScopesTrustedClientVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = new TrustedClientRef('one');
        $ref = UserConsentedScopesTrustedClientVO::from($value);
        $this->assertEquals(new TrustedClientRef('one'), $ref->value());
        $other = UserConsentedScopesTrustedClientVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = UserConsentedScopesTrustedClientVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = UserConsentedScopesTrustedClientVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(UserConsentedScopesTrustedClientVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = UserConsentedScopesTrustedClientVO::from(new TrustedClientRef('one'));
        $same = UserConsentedScopesTrustedClientVO::from(new TrustedClientRef('one'));
        $other = UserConsentedScopesTrustedClientVO::from(new TrustedClientRef('other'));
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
}
